const prisma = require('../prisma');

// Kardex de un producto: movimientos ordenados con saldo corrido.
async function kardex(productId) {
  productId = Number(productId);
  const product = await prisma.product.findUnique({ where: { id: productId } });
  if (!product) return null;

  const movements = await prisma.stockMovement.findMany({
    where: { productId },
    orderBy: [{ date: 'asc' }, { id: 'asc' }],
  });

  let balance = 0;
  const rows = movements.map((m) => {
    balance += m.quantityIn - m.quantityOut;
    return {
      id: m.id,
      date: m.date,
      type: m.type,
      reference: m.reference,
      quantityIn: m.quantityIn,
      quantityOut: m.quantityOut,
      balance,
    };
  });

  return { product, movements: rows };
}

// Control de inventario: entradas, salidas y existencia por producto.
async function inventoryControl() {
  const products = await prisma.product.findMany({
    include: { category: true, movements: true },
    orderBy: { name: 'asc' },
  });

  return products.map((p) => {
    const entradas = p.movements.reduce((a, m) => a + m.quantityIn, 0);
    const salidas = p.movements.reduce((a, m) => a + m.quantityOut, 0);
    return {
      id: p.id,
      code: p.code,
      name: p.name,
      category: p.category ? p.category.name : null,
      unit: p.unit,
      entradas,
      salidas,
      existencia: p.stock,
      minStock: p.minStock,
      active: p.active,
    };
  });
}

// Reporte: productos por agotarse (stock <= stock mínimo, activos).
async function lowStock() {
  const products = await prisma.product.findMany({
    where: { active: true },
    include: { category: true },
    orderBy: { name: 'asc' },
  });
  return products
    .filter((p) => p.stock <= p.minStock)
    .map((p) => ({
      code: p.code,
      name: p.name,
      category: p.category ? p.category.name : null,
      stock: p.stock,
      minStock: p.minStock,
      faltante: Math.max(0, p.minStock - p.stock),
    }));
}

// Reporte de utilidad por producto (incluye lo vendido y la utilidad real generada).
async function profit() {
  const products = await prisma.product.findMany({
    include: { saleItems: true },
    orderBy: { name: 'asc' },
  });

  return products.map((p) => {
    const soldQty = p.saleItems.reduce((a, s) => a + s.quantity, 0);
    const revenue = p.saleItems.reduce((a, s) => a + s.total, 0);
    const unitProfit = p.price - p.cost;
    const totalProfit = revenue - soldQty * p.cost;
    return {
      code: p.code,
      name: p.name,
      cost: p.cost,
      price: p.price,
      unitProfit,
      soldQty,
      revenue,
      totalProfit,
    };
  });
}

// Reporte de ventas por día.
async function salesByDay({ from, to } = {}) {
  const where = {};
  if (from || to) {
    where.date = {};
    if (from) where.date.gte = new Date(from);
    if (to) where.date.lte = new Date(`${to}T23:59:59`);
  }
  const sales = await prisma.sale.findMany({ where, orderBy: { date: 'asc' } });

  const map = new Map();
  for (const s of sales) {
    const key = new Date(s.date).toISOString().slice(0, 10);
    const entry = map.get(key) || { date: key, total: 0, count: 0 };
    entry.total += s.total;
    entry.count += 1;
    map.set(key, entry);
  }
  return Array.from(map.values()).sort((a, b) => (a.date < b.date ? 1 : -1));
}

// Resumen para el panel principal (dashboard).
async function dashboard() {
  const [products, lowStockList, customers] = await Promise.all([
    prisma.product.findMany(),
    lowStock(),
    prisma.customer.count(),
  ]);

  const today = new Date().toISOString().slice(0, 10);
  const todaySales = await prisma.sale.findMany({
    where: { date: { gte: new Date(`${today}T00:00:00`), lte: new Date(`${today}T23:59:59`) } },
  });
  const credits = await prisma.sale.findMany({
    where: { type: 'CREDIT' },
    include: { payments: true },
  });
  const receivable = credits.reduce((acc, s) => {
    const paid = s.payments.reduce((a, p) => a + p.amount, 0);
    return acc + (s.total - paid);
  }, 0);

  const inventoryValueCost = products.reduce((a, p) => a + p.stock * p.cost, 0);
  const inventoryValuePrice = products.reduce((a, p) => a + p.stock * p.price, 0);

  return {
    totalProducts: products.length,
    activeProducts: products.filter((p) => p.active).length,
    lowStockCount: lowStockList.length,
    todaySalesTotal: todaySales.reduce((a, s) => a + s.total, 0),
    todaySalesCount: todaySales.length,
    receivable,
    customers,
    inventoryValueCost,
    inventoryValuePrice,
    lowStockList: lowStockList.slice(0, 8),
  };
}

module.exports = { kardex, inventoryControl, lowStock, profit, salesByDay, dashboard };

