const router = require('express').Router();
const prisma = require('../prisma');
const ah = require('../utils/asyncHandler');
const ApiError = require('../utils/ApiError');

// Listar categorías con sus subcategorías
router.get('/', ah(async (req, res) => {
  const categories = await prisma.category.findMany({
    include: { subcategories: { orderBy: { name: 'asc' } }, _count: { select: { products: true } } },
    orderBy: { name: 'asc' },
  });
  res.json(categories);
}));

router.post('/', ah(async (req, res) => {
  const { name } = req.body;
  if (!name || !name.trim()) throw new ApiError(400, 'El nombre de la categoría es obligatorio.');
  const exists = await prisma.category.findUnique({ where: { name: name.trim() } });
  if (exists) throw new ApiError(400, 'Ya existe esa categoría.');
  const cat = await prisma.category.create({ data: { name: name.trim() } });
  res.status(201).json(cat);
}));

router.put('/:id', ah(async (req, res) => {
  const { name } = req.body;
  const cat = await prisma.category.update({
    where: { id: Number(req.params.id) },
    data: { name: name.trim() },
  });
  res.json(cat);
}));

router.delete('/:id', ah(async (req, res) => {
  const id = Number(req.params.id);
  const count = await prisma.product.count({ where: { categoryId: id } });
  if (count > 0) throw new ApiError(400, 'No se puede eliminar: hay productos en esta categoría.');
  await prisma.category.delete({ where: { id } });
  res.json({ ok: true });
}));

// Subcategorías
router.post('/:id/subcategories', ah(async (req, res) => {
  const categoryId = Number(req.params.id);
  const { name } = req.body;
  if (!name || !name.trim()) throw new ApiError(400, 'El nombre de la subcategoría es obligatorio.');
  const sub = await prisma.subcategory.create({ data: { name: name.trim(), categoryId } });
  res.status(201).json(sub);
}));

router.delete('/subcategories/:subId', ah(async (req, res) => {
  await prisma.subcategory.delete({ where: { id: Number(req.params.subId) } });
  res.json({ ok: true });
}));

module.exports = router;

