        try { await API.post(`/categories/${catId}/subcategories`, { name: box.querySelector('#s_name').value }); U.closeModal(); U.toast('Subcategoría creada.', 'success'); load(); }
        catch (e) { U.toast(e.message, 'error'); }
      };
