router.post('/:id/stock-adjustment', ah(async (req, res) => {
  const id = Number(req.params.id);
  const qty = Number(req.body.quantity);
  if (!qty) throw new ApiError(400, 'Ingrese una cantidad distinta de cero.');

  const updated = await prisma.$transaction(async (tx) => {
    const p = await tx.product.findUnique({ where: { id } });
    if (!p) throw new ApiError(404, 'Producto no encontrado.');
    if (p.stock + qty < 0)
      throw new ApiError(400, `El ajuste dejaría el stock negativo (actual ${p.stock}).`);

    await tx.product.update({ where: { id }, data: { stock: { increment: qty } } });
    await tx.stockMovement.create({
      data: {
        productId: id,
        type: 'ADJUSTMENT',
        quantityIn: qty > 0 ? qty : 0,
        quantityOut: qty < 0 ? -qty : 0,
        reference: req.body.reason ? req.body.reason : 'Ajuste manual de stock',
      },
    });
    return tx.product.findUnique({ where: { id } });
  });
  res.json(updated);
}));

