const router = require('express').Router();
const prisma = require('../prisma');
const ah = require('../utils/asyncHandler');
const ApiError = require('../utils/ApiError');

// Listar productos (con filtros opcionales: búsqueda, categoría, estado)
router.get('/', ah(async (req, res) => {
  const { q, categoryId, active } = req.query;
  const where = {};
  if (q) where.OR = [
    { name: { contains: q, mode: 'insensitive' } },
    { code: { contains: q, mode: 'insensitive' } },
  ];
  if (categoryId) where.categoryId = Number(categoryId);
  if (active === 'true') where.active = true;
  if (active === 'false') where.active = false;

  const products = await prisma.product.findMany({
    where,
    include: { category: true, subcategory: true },
    orderBy: { name: 'asc' },
  });
  res.json(products);
}));

router.get('/:id', ah(async (req, res) => {
  const product = await prisma.product.findUnique({
    where: { id: Number(req.params.id) },
    include: { category: true, subcategory: true },
  });
  if (!product) throw new ApiError(404, 'Producto no encontrado.');
  res.json(product);
}));

// Crear producto. Si trae stock inicial, se registra como movimiento INITIAL.
router.post('/', ah(async (req, res) => {
  const b = req.body;
  if (!b.code || !b.name) throw new ApiError(400, 'El código y el nombre son obligatorios.');

  const exists = await prisma.product.findUnique({ where: { code: b.code.trim() } });
  if (exists) throw new ApiError(400, `Ya existe un producto con el código ${b.code}.`);

  const stock = Number(b.stock) || 0;

  const product = await prisma.$transaction(async (tx) => {
    const p = await tx.product.create({
      data: {
        code: b.code.trim(),
        name: b.name.trim(),
        categoryId: b.categoryId ? Number(b.categoryId) : null,
        subcategoryId: b.subcategoryId ? Number(b.subcategoryId) : null,
        unit: b.unit || 'Unidad',
        supplier: b.supplier || null,
        cost: Number(b.cost) || 0,
        price: Number(b.price) || 0,
        minStock: Number(b.minStock) || 0,
        stock,
        active: b.active !== undefined ? !!b.active : true,
      },
    });
    if (stock > 0) {
      await tx.stockMovement.create({
        data: { productId: p.id, type: 'INITIAL', quantityIn: stock, reference: 'Stock inicial' },
      });
    }
    return p;
  });

  res.status(201).json(product);
}));

// Actualizar producto (no toca el stock directamente para no romper el kardex)
router.put('/:id', ah(async (req, res) => {
  const id = Number(req.params.id);
  const b = req.body;
  const product = await prisma.product.findUnique({ where: { id } });
  if (!product) throw new ApiError(404, 'Producto no encontrado.');

  if (b.code && b.code.trim() !== product.code) {
    const dup = await prisma.product.findUnique({ where: { code: b.code.trim() } });
    if (dup) throw new ApiError(400, `Ya existe un producto con el código ${b.code}.`);
  }

  const updated = await prisma.product.update({
    where: { id },
    data: {
      code: b.code !== undefined ? b.code.trim() : undefined,
      name: b.name !== undefined ? b.name.trim() : undefined,
      categoryId: b.categoryId !== undefined ? (b.categoryId ? Number(b.categoryId) : null) : undefined,
      subcategoryId: b.subcategoryId !== undefined ? (b.subcategoryId ? Number(b.subcategoryId) : null) : undefined,
      unit: b.unit,
      supplier: b.supplier,
      cost: b.cost !== undefined ? Number(b.cost) : undefined,
      price: b.price !== undefined ? Number(b.price) : undefined,
      minStock: b.minStock !== undefined ? Number(b.minStock) : undefined,
      active: b.active !== undefined ? !!b.active : undefined,
    },
  });
  res.json(updated);
}));

// Eliminar producto (solo si no tiene movimientos asociados)
router.delete('/:id', ah(async (req, res) => {
  const id = Number(req.params.id);
  const movements = await prisma.stockMovement.count({ where: { productId: id } });
  if (movements > 0)
    throw new ApiError(400, 'No se puede eliminar: el producto tiene movimientos. Desactívelo en su lugar.');
  await prisma.product.delete({ where: { id } });
  res.json({ ok: true });
}));

module.exports = router;

/* Módulo: Maestro de Productos */
window.Routes = window.Routes || {};
window.Routes.productos = {
  title: 'Productos',
  async render(view) {
    let categories = [];

    async function load() {
      view.innerHTML = '<div class="loader">Cargando productos…</div>';
      const q = document.getElementById ? '' : '';
      const [products, cats] = await Promise.all([
        API.get('/products', { q: state.q, categoryId: state.categoryId }),
        API.get('/categories'),
      ]);
      categories = cats;
      paint(products);
    }

    const state = { q: '', categoryId: '' };

    function paint(products) {
      view.innerHTML = `
        <div class="panel">
          <div class="panel-head">
            <h2>Maestro de Productos</h2>
            <button class="btn primary" id="btnNew">+ Nuevo producto</button>
          </div>
          <div class="panel-body">
            <div class="toolbar">
              <input class="search" id="search" placeholder="Buscar por nombre o código…" value="${U.escapeHtml(state.q)}" />
              <select id="catFilter" style="max-width:200px">
                <option value="">Todas las categorías</option>
                ${categories.map((c) => `<option value="${c.id}" ${state.categoryId == c.id ? 'selected' : ''}>${U.escapeHtml(c.name)}</option>`).join('')}
              </select>
            </div>
            ${U.table(
              [
                { key: 'code', label: 'Código' },
                { key: 'name', label: 'Nombre' },
                { key: 'cat', label: 'Categoría', render: (r) => U.escapeHtml(r.category ? r.category.name : '—') },
                { key: 'unit', label: 'Unidad' },
                { key: 'supplier', label: 'Proveedor', render: (r) => U.escapeHtml(r.supplier || '—') },
                { key: 'cost', label: 'Costo', num: true, render: (r) => U.money(r.cost) },
                { key: 'price', label: 'P. Venta', num: true, render: (r) => U.money(r.price) },
                { key: 'stock', label: 'Stock', num: true, render: (r) => r.stock <= r.minStock ? `<span class="text-red">${r.stock}</span>` : r.stock },
                { key: 'min', label: 'Mín', num: true, render: (r) => r.minStock },
                { key: 'estado', label: 'Estado', render: (r) => r.active ? '<span class="badge green">Activo</span>' : '<span class="badge gray">Inactivo</span>' },
                { key: 'acc', label: '', render: (r) => `<button class="btn-icon" data-edit="${r.id}" title="Editar">✏️</button><button class="btn-icon" data-del="${r.id}" title="Eliminar">🗑️</button>` },
              ],
              products,
              { empty: 'No hay productos. Crea el primero con “Nuevo producto”.' }
            )}
          </div>
