const prisma = require('../prisma');
const ApiError = require('../utils/ApiError');

// Calcula el estado de una venta a crédito según lo abonado
function computeStatus(total, paid) {
  if (paid >= total) return 'PAID';
  if (paid > 0) return 'PARTIAL';
  return 'PENDING';
}

// Registrar una venta (contado o crédito).
// Descuenta el stock de cada producto y deja el movimiento en el kardex.
async function create({ items, type = 'CASH', customer, customerId, dueDate, date }) {
  if (!Array.isArray(items) || items.length === 0)
    throw new ApiError(400, 'Debe agregar al menos un producto a la venta.');

  const normalized = items.map((it) => ({
    productId: Number(it.productId),
    quantity: Number(it.quantity),
    unitPrice: it.unitPrice != null ? Number(it.unitPrice) : null,
  }));

  for (const it of normalized) {
    if (!it.productId) throw new ApiError(400, 'Hay un producto inválido en la venta.');
    if (!it.quantity || it.quantity <= 0)
      throw new ApiError(400, 'Las cantidades deben ser mayores a cero.');
  }

  return prisma.$transaction(async (tx) => {
    // Resolver cliente (para crédito)
    let resolvedCustomerId = customerId ? Number(customerId) : null;
    if (type === 'CREDIT' && !resolvedCustomerId) {
      if (!customer || !customer.trim())
        throw new ApiError(400, 'Una venta a crédito requiere un cliente.');
      const existing = await tx.customer.findUnique({ where: { name: customer.trim() } });
      resolvedCustomerId = existing
        ? existing.id
        : (await tx.customer.create({ data: { name: customer.trim() } })).id;
    }

    // Validar stock y precios
    const lineData = [];
    let total = 0;
    for (const it of normalized) {
      const product = await tx.product.findUnique({ where: { id: it.productId } });
      if (!product) throw new ApiError(404, `Producto ${it.productId} no existe.`);
      if (product.stock < it.quantity)
        throw new ApiError(
          400,
          `Stock insuficiente de "${product.name}". Disponible: ${product.stock}, solicitado: ${it.quantity}.`
        );
      const unitPrice = it.unitPrice != null ? it.unitPrice : product.price;
      const lineTotal = unitPrice * it.quantity;
      total += lineTotal;
      lineData.push({ productId: it.productId, quantity: it.quantity, unitPrice, total: lineTotal });
    }

    const sale = await tx.sale.create({
      data: {
        type,
        total,
        date: date ? new Date(date) : undefined,
        customerId: resolvedCustomerId,
        dueDate: type === 'CREDIT' && dueDate ? new Date(dueDate) : null,
        status: type === 'CREDIT' ? 'PENDING' : null,
        items: { create: lineData },
      },
    });

    // Descontar stock + movimientos de kardex
    for (const line of lineData) {
      await tx.product.update({
        where: { id: line.productId },
        data: { stock: { decrement: line.quantity } },
      });
      await tx.stockMovement.create({
        data: {
          productId: line.productId,
          type: 'SALE',
          quantityOut: line.quantity,
          date: date ? new Date(date) : undefined,
          reference: `Venta #${sale.id}`,
        },
      });
    }

    return tx.sale.findUnique({
      where: { id: sale.id },
      include: { items: { include: { product: true } }, customer: true, payments: true },
    });
  });
}

function list({ from, to, type } = {}) {
  const where = {};
  if (type) where.type = type;
  if (from || to) {
    where.date = {};
    if (from) where.date.gte = new Date(from);
    if (to) where.date.lte = new Date(`${to}T23:59:59`);
  }
  return prisma.sale.findMany({
    where,
    include: { items: { include: { product: true } }, customer: true, payments: true },
    orderBy: { date: 'desc' },
  });
}

// ----- Cartera (cuentas por cobrar) -----

// Lista de créditos con saldo calculado
async function listCredits({ onlyPending } = {}) {
  const sales = await prisma.sale.findMany({
    where: { type: 'CREDIT' },
    include: { customer: true, payments: true, items: { include: { product: true } } },
    orderBy: { date: 'desc' },
  });

  const result = sales.map((s) => {
    const paid = s.payments.reduce((a, p) => a + p.amount, 0);
    const balance = s.total - paid;
    return { ...s, paid, balance };
  });

  return onlyPending ? result.filter((s) => s.balance > 0.0001) : result;
}

// Registrar un abono y recalcular el estado del crédito
async function addPayment(saleId, amount, date) {
  saleId = Number(saleId);
  amount = Number(amount);
  if (!amount || amount <= 0) throw new ApiError(400, 'El abono debe ser mayor a cero.');

  return prisma.$transaction(async (tx) => {
    const sale = await tx.sale.findUnique({ where: { id: saleId }, include: { payments: true } });
    if (!sale) throw new ApiError(404, 'El crédito no existe.');
    if (sale.type !== 'CREDIT') throw new ApiError(400, 'La venta no es a crédito.');

    const paid = sale.payments.reduce((a, p) => a + p.amount, 0);
    const balance = sale.total - paid;
    if (amount > balance + 0.0001)
      throw new ApiError(400, `El abono supera el saldo pendiente (${balance}).`);

    await tx.payment.create({
      data: { saleId, amount, date: date ? new Date(date) : undefined },
    });

    const newStatus = computeStatus(sale.total, paid + amount);
    await tx.sale.update({ where: { id: saleId }, data: { status: newStatus } });

    return tx.sale.findUnique({
      where: { id: saleId },
      include: { payments: true, customer: true },
    });
  });
}

// Historial completo de un cliente
async function customerHistory(customerId) {
  customerId = Number(customerId);
  const customer = await prisma.customer.findUnique({
    where: { id: customerId },
    include: {
      sales: {
        where: { type: 'CREDIT' },
        include: { payments: true, items: { include: { product: true } } },
        orderBy: { date: 'desc' },
      },
    },
  });
  if (!customer) throw new ApiError(404, 'El cliente no existe.');

  let totalDebt = 0;
  let lastPaymentDate = null;
  const sales = customer.sales.map((s) => {
    const paid = s.payments.reduce((a, p) => a + p.amount, 0);
    const balance = s.total - paid;
    totalDebt += balance;
    for (const p of s.payments) {
      if (!lastPaymentDate || new Date(p.date) > new Date(lastPaymentDate)) lastPaymentDate = p.date;
    }
    return { ...s, paid, balance };
  });

  return { customer: { id: customer.id, name: customer.name, phone: customer.phone }, sales, totalDebt, lastPaymentDate };
}

module.exports = { create, list, listCredits, addPayment, customerHistory };

