const prisma = require('../prisma');
const ApiError = require('../utils/ApiError');

// Crear un conteo físico (borrador). Toma el stock actual del sistema como referencia.
// items: [{ productId, physicalQty, observation }]
// Si se pasa categoryId, se genera el conteo solo para esa categoría tomando todos sus productos.
async function create({ note, items, categoryId }) {
  let lines = [];

  if (categoryId && (!items || items.length === 0)) {
    const products = await prisma.product.findMany({ where: { categoryId: Number(categoryId), active: true } });
    lines = products.map((p) => ({ productId: p.id, systemQty: p.stock, physicalQty: p.stock, difference: 0, observation: null }));
  } else {
    if (!Array.isArray(items) || items.length === 0)
      throw new ApiError(400, 'Debe registrar al menos un producto en el conteo.');
    for (const it of items) {
      const product = await prisma.product.findUnique({ where: { id: Number(it.productId) } });
      if (!product) throw new ApiError(404, `Producto ${it.productId} no existe.`);
      const physicalQty = Number(it.physicalQty);
      lines.push({
        productId: product.id,
        systemQty: product.stock,
        physicalQty,
        difference: physicalQty - product.stock,
        observation: it.observation || null,
      });
    }
  }

  return prisma.physicalInventory.create({
    data: { note: note || null, status: 'DRAFT', items: { create: lines } },
    include: { items: { include: { product: true } } },
  });
}

function list() {
  return prisma.physicalInventory.findMany({
    include: { items: { include: { product: true } } },
    orderBy: { date: 'desc' },
  });
}

function get(id) {
  return prisma.physicalInventory.findUnique({
    where: { id: Number(id) },
    include: { items: { include: { product: true } } },
  });
}

// Aprobar el inventario físico: genera los ajustes de stock y movimientos de kardex
// para todas las diferencias distintas de cero.
async function approve(id) {
  id = Number(id);
  return prisma.$transaction(async (tx) => {
    const inv = await tx.physicalInventory.findUnique({ where: { id }, include: { items: true } });
    if (!inv) throw new ApiError(404, 'El inventario físico no existe.');
    if (inv.status === 'APPROVED') throw new ApiError(400, 'Este inventario ya fue aprobado.');

    for (const item of inv.items) {
      if (item.difference === 0) continue;
      // Ajustar el stock al valor físico contado
      await tx.product.update({ where: { id: item.productId }, data: { stock: item.physicalQty } });
      await tx.stockMovement.create({
        data: {
          productId: item.productId,
          type: 'ADJUSTMENT',
          quantityIn: item.difference > 0 ? item.difference : 0,
          quantityOut: item.difference < 0 ? -item.difference : 0,
          reference: `Ajuste inventario físico #${inv.id}`,
        },
      });
    }

    return tx.physicalInventory.update({
      where: { id },
      data: { status: 'APPROVED' },
      include: { items: { include: { product: true } } },
    });
  });
}

module.exports = { create, list, get, approve };

