/* Cliente de la API REST (objeto global API) con soporte multi-kiosko */
const API = (() => {
  const base = '/api';
  const KEY = 'activeKioskId';

  const getKiosk = () => localStorage.getItem(KEY) || '';
  const setKiosk = (id) => { if (id) localStorage.setItem(KEY, id); else localStorage.removeItem(KEY); };

  async function request(method, path, body) {
    const opts = { method, headers: {} };
    const kioskId = getKiosk();
    if (kioskId) opts.headers['X-Kiosk-Id'] = kioskId;
    if (body !== undefined) {
      opts.headers['Content-Type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    const res = await fetch(base + path, opts);
    let data = null;
    const text = await res.text();
    if (text) { try { data = JSON.parse(text); } catch { data = text; } }
    if (!res.ok) throw new Error((data && data.error) || `Error ${res.status}`);
    return data;
  }

  const qs = (params) => {
    const clean = Object.entries(params || {}).filter(([, v]) => v !== '' && v != null);
    return clean.length ? '?' + clean.map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&') : '';
  };

  return {
    get: (path, params) => request('GET', path + qs(params)),
    post: (path, body) => request('POST', path, body),
    put: (path, body) => request('PUT', path, body),
    del: (path) => request('DELETE', path),
    getKiosk,
    setKiosk,
  };
})();

