/* ===================================================
   Sistema del Kiosco — Sistema de diseño
   =================================================== */
:root {
  /* Neutrales */
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --border: #e7e9ee;
  --border-strong: #d6dae1;

  /* Texto */
  --text: #1a1d24;
  --text-2: #5b6472;
  --muted: #8a93a2;

  /* Marca */
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-soft: #eef0fe;
  --primary-ring: rgba(79, 70, 229, 0.16);

  /* Sidebar */
  --sb-bg: #14161d;
  --sb-bg-2: #1c1f29;
  --sb-text: #9aa3b2;
  --sb-text-hover: #ffffff;
  --sb-active: #4f46e5;

  /* Estados */
  --green: #0f9d58;
  --green-soft: #e6f6ee;
  --red: #e11d48;
  --red-soft: #fdeef1;
  --amber: #d97706;
  --amber-soft: #fdf3e3;
  --blue: #2563eb;
  --blue-soft: #e8f0ff;

  /* Radios y sombras */
  --r-sm: 8px;
  --r-md: 12px;
  --r-lg: 16px;
  --shadow-xs: 0 1px 2px rgba(16, 24, 40, 0.05);
  --shadow-sm: 0 1px 3px rgba(16, 24, 40, 0.08), 0 1px 2px rgba(16, 24, 40, 0.04);
  --shadow-md: 0 4px 12px rgba(16, 24, 40, 0.08), 0 2px 4px rgba(16, 24, 40, 0.04);
  --shadow-lg: 0 20px 48px rgba(16, 24, 40, 0.18);

  --sidebar-w: 256px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }

body {
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
  letter-spacing: -0.006em;
}

::selection { background: var(--primary-ring); }

/* Scrollbars discretos */
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-thumb { background: #c9cdd6; border-radius: 999px; border: 2px solid transparent; background-clip: content-box; }
*::-webkit-scrollbar-thumb:hover { background: #aeb4c0; background-clip: content-box; }

.app { display: flex; min-height: 100vh; }

/* ---------- Sidebar ---------- */
.sidebar {
  width: var(--sidebar-w);
  background: var(--sb-bg);
  color: var(--sb-text);
  display: flex;
  flex-direction: column;
  position: fixed;
  top: 0; bottom: 0; left: 0;
  z-index: 30;
  transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
  border-right: 1px solid rgba(255, 255, 255, 0.04);
}
.brand {
  display: flex; align-items: center; gap: 12px;
  padding: 22px 22px 18px;
  margin-bottom: 4px;
}
.brand-logo {
  font-size: 22px; width: 42px; height: 42px;
  display: grid; place-items: center;
  background: linear-gradient(145deg, #4f46e5, #6366f1);
  border-radius: 12px;
  box-shadow: 0 4px 12px rgba(79, 70, 229, 0.4);
}
.brand strong { display: block; color: #fff; font-size: 16px; font-weight: 700; letter-spacing: -0.01em; font-family: 'Plus Jakarta Sans', 'Inter', sans-serif; }
.brand small { color: var(--muted); font-size: 12px; }

.nav { flex: 1; padding: 8px 14px; overflow-y: auto; }
.nav a {
  display: flex; align-items: center; gap: 11px;
  padding: 9px 12px; margin: 1px 0;
  color: var(--sb-text); text-decoration: none;
  border-radius: 9px; font-weight: 500; font-size: 14px;
  position: relative;
  transition: background 0.15s, color 0.15s;
}
.nav a:hover { background: var(--sb-bg-2); color: var(--sb-text-hover); }
.nav a.active { background: var(--sb-active); color: #fff; box-shadow: 0 4px 12px rgba(79, 70, 229, 0.35); }
.nav a.active .ico { opacity: 1; }
.nav a .ico { width: 20px; text-align: center; font-size: 15px; opacity: 0.85; }
.nav-group {
  font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.08em;
  color: #5a6473; padding: 16px 12px 6px; font-weight: 700;
}
.sidebar-footer { padding: 14px 22px; color: #4a5363; font-size: 11.5px; border-top: 1px solid rgba(255, 255, 255, 0.05); }

/* ---------- Main ---------- */
.main { flex: 1; margin-left: var(--sidebar-w); display: flex; flex-direction: column; min-width: 0; }
.topbar {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: saturate(180%) blur(8px);
  border-bottom: 1px solid var(--border);
  padding: 0 28px; height: 64px;
  display: flex; align-items: center; gap: 16px;
  position: sticky; top: 0; z-index: 20;
}
.topbar h1 { font-size: 20px; font-weight: 700; flex: 1; letter-spacing: -0.02em; font-family: 'Plus Jakarta Sans', 'Inter', sans-serif; }
.topbar-right { color: var(--muted); display: flex; align-items: center; gap: 18px; }
.today { font-size: 13px; text-transform: capitalize; }
.kiosk-picker {
  display: flex; align-items: center; gap: 7px;
  background: var(--surface); border: 1px solid var(--border-strong); border-radius: 10px;
  padding: 5px 12px; box-shadow: var(--shadow-xs);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.kiosk-picker:hover { border-color: var(--primary); }
.kiosk-picker .ico { font-size: 14px; }
.kiosk-picker select { border: none; background: transparent; font-weight: 600; color: var(--text); padding: 2px; cursor: pointer; max-width: 200px; font-size: 13.5px; }
.kiosk-picker select:focus { box-shadow: none; }
.hamburger { display: none; background: none; border: none; font-size: 22px; cursor: pointer; color: var(--text-2); }
.view { padding: 28px; flex: 1; max-width: 1500px; width: 100%; }

/* ---------- KPI cards ---------- */
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(248px, 1fr)); gap: 18px; margin-bottom: 26px; }
.kpi {
  background: var(--surface); border-radius: var(--r-md);
  padding: 20px; box-shadow: var(--shadow-sm); border: 1px solid var(--border);
  display: flex; gap: 16px; align-items: flex-start;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.kpi:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.kpi-icon {
  width: 44px; height: 44px; flex-shrink: 0;
  display: grid; place-items: center; border-radius: 11px;
  font-size: 20px; background: var(--surface-2);
}
.kpi-body { min-width: 0; flex: 1; }
.kpi .label { color: var(--text-2); font-size: 13px; font-weight: 500; }
.kpi .value { font-size: 25px; font-weight: 800; margin-top: 5px; letter-spacing: -0.03em; font-family: 'Plus Jakarta Sans', 'Inter', sans-serif; color: var(--text); }
.kpi .sub { color: var(--muted); font-size: 12px; margin-top: 4px; }
.kpi.accent-green .kpi-icon { background: var(--green-soft); }
.kpi.accent-green .value { color: var(--green); }
.kpi.accent-red .kpi-icon { background: var(--red-soft); }
.kpi.accent-red .value { color: var(--red); }
.kpi.accent-blue .kpi-icon { background: var(--blue-soft); }
.kpi.accent-blue .value { color: var(--blue); }
.kpi.accent-amber .kpi-icon { background: var(--amber-soft); }
.kpi.accent-amber .value { color: var(--amber); }

/* ---------- Paneles ---------- */
.panel {
  background: var(--surface); border-radius: var(--r-md);
  box-shadow: var(--shadow-sm); border: 1px solid var(--border);
  margin-bottom: 22px; overflow: hidden;
}
.panel-head {
  display: flex; align-items: center; gap: 12px;
  padding: 18px 22px; border-bottom: 1px solid var(--border);
}
.panel-head h2 { font-size: 16px; font-weight: 700; flex: 1; letter-spacing: -0.01em; font-family: 'Plus Jakarta Sans', 'Inter', sans-serif; }
.panel-body { padding: 22px; }
.panel-body.flush { padding: 0; }

/* ---------- Toolbar ---------- */
.toolbar { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-bottom: 18px; }
.toolbar .spacer { flex: 1; }

/* ---------- Tablas ---------- */
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; }
th, td { padding: 13px 18px; text-align: left; border-bottom: 1px solid var(--border); white-space: nowrap; }
th {
  background: var(--surface-2); color: var(--muted); font-size: 11px;
  text-transform: uppercase; letter-spacing: 0.05em; font-weight: 700;
}
tbody tr { transition: background 0.12s; }
tbody tr:last-child td { border-bottom: none; }
tbody tr:hover { background: var(--primary-soft); }
td { font-size: 13.5px; color: var(--text-2); }
td:first-child, td.strong { color: var(--text); font-weight: 600; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
.empty { text-align: center; color: var(--muted); padding: 52px 20px; font-size: 14px; }

/* ---------- Botones ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  padding: 9px 16px; border-radius: var(--r-sm); border: 1px solid var(--border-strong);
  background: var(--surface); color: var(--text);
  font-weight: 600; cursor: pointer; font-size: 13.5px; font-family: inherit;
