/* Módulo: Panel principal (dashboard) */
window.Routes = window.Routes || {};
window.Routes.dashboard = {
  title: 'Panel',
  async render(view) {
    view.innerHTML = '<div class="loader">Cargando panel…</div>';
    const d = await API.get('/reports/dashboard');

    const kpis = [
      { icon: '💵', label: 'Ventas de hoy', value: U.money(d.todaySalesTotal), sub: `${d.todaySalesCount} venta(s)`, accent: 'green' },
      { icon: '🧾', label: 'Por cobrar (cartera)', value: U.money(d.receivable), sub: `${d.customers} cliente(s)`, accent: 'red' },
      { icon: '⚠️', label: 'Productos por agotarse', value: d.lowStockCount, sub: 'en o bajo el mínimo', accent: 'amber' },
      { icon: '📦', label: 'Productos activos', value: d.activeProducts, sub: `${d.totalProducts} en total`, accent: 'blue' },
      { icon: '💰', label: 'Valor inventario (costo)', value: U.money(d.inventoryValueCost), sub: 'capital en mercancía' },
      { icon: '🏷️', label: 'Valor inventario (venta)', value: U.money(d.inventoryValuePrice), sub: 'si se vende todo' },
    ];

    view.innerHTML = `
      <div class="cards">
        ${kpis.map((k) => `
          <div class="kpi with-icon ${k.accent ? 'accent-' + k.accent : ''}">
            <div class="kpi-icon">${k.icon}</div>
            <div class="kpi-body">
              <div class="label">${k.label}</div>
              <div class="value">${k.value}</div>
              <div class="sub">${k.sub}</div>
            </div>
          </div>`).join('')}
      </div>
      <div class="panel">
        <div class="panel-head"><h2>⚠️ Productos por agotarse</h2>
          <a class="btn sm" href="#/reportes">Ver reporte completo</a></div>
        <div class="panel-body flush">
          ${U.table(
            [
              { key: 'code', label: 'Código' },
              { key: 'name', label: 'Producto' },
              { key: 'category', label: 'Categoría', render: (r) => U.escapeHtml(r.category || '—') },
              { key: 'stock', label: 'Stock', num: true, render: (r) => `<span class="text-red">${r.stock}</span>` },
              { key: 'minStock', label: 'Mínimo', num: true },
            ],
            d.lowStockList,
            { empty: '¡Todo en orden! Ningún producto por agotarse.' }
          )}
        </div>
      </div>`;
  },
};

/* Módulo: Maestro de Productos */
window.Routes = window.Routes || {};
window.Routes.productos = {
  title: 'Productos',
  async render(view) {
    let categories = [];

    async function load() {
      view.innerHTML = '<div class="loader">Cargando productos…</div>';
      const q = document.getElementById ? '' : '';
      const [products, cats] = await Promise.all([
        API.get('/products', { q: state.q, categoryId: state.categoryId }),
        API.get('/categories'),
      ]);
      categories = cats;
      paint(products);
    }

    const state = { q: '', categoryId: '' };

    function paint(products) {
      view.innerHTML = `
        <div class="panel">
          <div class="panel-head">
            <h2>Maestro de Productos</h2>
            <button class="btn primary" id="btnNew">+ Nuevo producto</button>
          </div>
          <div class="panel-body">
            <div class="toolbar">
              <input class="search" id="search" placeholder="Buscar por nombre o código…" value="${U.escapeHtml(state.q)}" />
              <select id="catFilter" style="max-width:200px">
                <option value="">Todas las categorías</option>
                ${categories.map((c) => `<option value="${c.id}" ${state.categoryId == c.id ? 'selected' : ''}>${U.escapeHtml(c.name)}</option>`).join('')}
              </select>
            </div>
            ${U.table(
              [
                { key: 'code', label: 'Código' },
                { key: 'name', label: 'Nombre' },
                { key: 'cat', label: 'Categoría', render: (r) => U.escapeHtml(r.category ? r.category.name : '—') },
                { key: 'unit', label: 'Unidad' },
                { key: 'supplier', label: 'Proveedor', render: (r) => U.escapeHtml(r.supplier || '—') },
                { key: 'cost', label: 'Costo', num: true, render: (r) => U.money(r.cost) },
                { key: 'price', label: 'P. Venta', num: true, render: (r) => U.money(r.price) },
                { key: 'stock', label: 'Stock', num: true, render: (r) => r.stock <= r.minStock ? `<span class="text-red">${r.stock}</span>` : r.stock },
                { key: 'min', label: 'Mín', num: true, render: (r) => r.minStock },
                { key: 'estado', label: 'Estado', render: (r) => r.active ? '<span class="badge green">Activo</span>' : '<span class="badge gray">Inactivo</span>' },
                { key: 'acc', label: '', render: (r) => `<button class="btn-icon" data-stock="${r.id}" title="Ajustar stock">📥</button><button class="btn-icon" data-edit="${r.id}" title="Editar">✏️</button><button class="btn-icon" data-del="${r.id}" title="Eliminar">🗑️</button>` },
              ],
              products,
              { empty: 'No hay productos. Crea el primero con “Nuevo producto”.' }
            )}
          </div>
        </div>`;

      document.getElementById('btnNew').onclick = () => openForm();
      const search = document.getElementById('search');
      search.oninput = debounce(() => { state.q = search.value; load(); }, 350);
      document.getElementById('catFilter').onchange = (e) => { state.categoryId = e.target.value; load(); };
      view.querySelectorAll('[data-edit]').forEach((b) => (b.onclick = () => openForm(products.find((p) => p.id == b.dataset.edit))));
      view.querySelectorAll('[data-del]').forEach((b) => (b.onclick = () => remove(b.dataset.del)));
      view.querySelectorAll('[data-stock]').forEach((b) => (b.onclick = () => openStock(products.find((p) => p.id == b.dataset.stock))));
    }

    function openStock(p) {
      const box = U.modal({
        title: `Ajustar stock · ${p.name}`,
        bodyHtml: `
          <p class="text-muted">Stock actual: <strong>${p.stock}</strong> ${U.escapeHtml(p.unit)}</p>
          <div class="grid-2">
            <div class="field"><label>Movimiento</label>
              <select id="s_type"><option value="in">Agregar (entrada)</option><option value="out">Quitar (salida)</option></select></div>
            <div class="field"><label>Cantidad</label><input id="s_qty" type="number" min="1" value="1" /></div>
          </div>
          <div class="field"><label>Motivo <span class="hint">(opcional)</span></label><input id="s_reason" placeholder="Ej: Producto dañado, ajuste manual…" /></div>
          <p class="text-muted">Nuevo stock: <strong id="s_preview">${p.stock}</strong></p>`,
        footerHtml: `<button class="btn" data-c>Cancelar</button><button class="btn primary" data-s>Aplicar ajuste</button>`,
      });

      const typeSel = box.querySelector('#s_type');
      const qtyInput = box.querySelector('#s_qty');
      const preview = box.querySelector('#s_preview');
      const calc = () => {
        const q = (Number(qtyInput.value) || 0) * (typeSel.value === 'out' ? -1 : 1);
        const next = p.stock + q;
        preview.textContent = next;
        preview.className = next < 0 ? 'text-red' : '';
      };
      typeSel.onchange = calc; qtyInput.oninput = calc; calc();

      box.querySelector('[data-c]').onclick = U.closeModal;
      box.querySelector('[data-s]').onclick = async () => {
        const q = (Number(qtyInput.value) || 0) * (typeSel.value === 'out' ? -1 : 1);
        if (!q) return U.toast('Ingresa una cantidad válida.', 'error');
        try {
          await API.post(`/products/${p.id}/stock-adjustment`, { quantity: q, reason: box.querySelector('#s_reason').value });
          U.closeModal(); U.toast('Stock ajustado.', 'success'); load();
        } catch (e) { U.toast(e.message, 'error'); }
      };
    }

    function openForm(p = null) {
      const isEdit = !!p;
      const catOptions = categories.map((c) => `<option value="${c.id}" ${p && p.categoryId == c.id ? 'selected' : ''}>${U.escapeHtml(c.name)}</option>`).join('');
      const subOptions = (catId) => {
        const cat = categories.find((c) => c.id == catId);
        if (!cat) return '';
        return cat.subcategories.map((s) => `<option value="${s.id}" ${p && p.subcategoryId == s.id ? 'selected' : ''}>${U.escapeHtml(s.name)}</option>`).join('');
      };

      const box = U.modal({
        title: isEdit ? 'Editar producto' : 'Nuevo producto',
        wide: true,
        bodyHtml: `
          <div class="grid-2">
            <div class="field"><label>Código *</label><input id="f_code" value="${U.escapeHtml(p?.code || '')}" ${isEdit ? '' : ''} /></div>
            <div class="field"><label>Nombre *</label><input id="f_name" value="${U.escapeHtml(p?.name || '')}" /></div>
          </div>
          <div class="grid-2">
            <div class="field"><label>Categoría</label><select id="f_cat"><option value="">—</option>${catOptions}</select></div>
            <div class="field"><label>Subcategoría</label><select id="f_sub"><option value="">—</option>${p ? subOptions(p.categoryId) : ''}</select></div>
          </div>
          <div class="grid-3">
            <div class="field"><label>Unidad de medida</label><input id="f_unit" value="${U.escapeHtml(p?.unit || 'Unidad')}" /></div>
            <div class="field"><label>Proveedor</label><input id="f_supplier" value="${U.escapeHtml(p?.supplier || '')}" /></div>
            <div class="field"><label>Estado</label><select id="f_active"><option value="true" ${!p || p.active ? 'selected' : ''}>Activo</option><option value="false" ${p && !p.active ? 'selected' : ''}>Inactivo</option></select></div>
          </div>
          <div class="grid-3">
            <div class="field"><label>Costo de compra</label><input id="f_cost" type="number" min="0" value="${p?.cost ?? 0}" /></div>
            <div class="field"><label>Precio de venta</label><input id="f_price" type="number" min="0" value="${p?.price ?? 0}" /></div>
            <div class="field"><label>Stock mínimo</label><input id="f_min" type="number" min="0" value="${p?.minStock ?? 0}" /></div>
          </div>
          ${isEdit ? '' : `<div class="field"><label>Stock inicial</label><input id="f_stock" type="number" min="0" value="0" /><span class="hint">Las compras y ventas ajustarán el stock automáticamente.</span></div>`}
        `,
        footerHtml: `<button class="btn" data-close-2>Cancelar</button><button class="btn primary" id="f_save">Guardar</button>`,
      });

      box.querySelector('[data-close-2]').onclick = U.closeModal;
      box.querySelector('#f_cat').onchange = (e) => { box.querySelector('#f_sub').innerHTML = '<option value="">—</option>' + subOptions(e.target.value); };

      box.querySelector('#f_save').onclick = async () => {
        const data = {
          code: box.querySelector('#f_code').value,
          name: box.querySelector('#f_name').value,
          categoryId: box.querySelector('#f_cat').value || null,
          subcategoryId: box.querySelector('#f_sub').value || null,
          unit: box.querySelector('#f_unit').value,
          supplier: box.querySelector('#f_supplier').value,
          cost: box.querySelector('#f_cost').value,
          price: box.querySelector('#f_price').value,
          minStock: box.querySelector('#f_min').value,
          active: box.querySelector('#f_active').value === 'true',
        };
        if (!isEdit) data.stock = box.querySelector('#f_stock').value;
        try {
          if (isEdit) await API.put('/products/' + p.id, data);
          else await API.post('/products', data);
          U.closeModal();
          U.toast('Producto guardado.', 'success');
          load();
        } catch (e) { U.toast(e.message, 'error'); }
      };
    }

    async function remove(id) {
      if (!(await U.confirm('¿Eliminar este producto?', { danger: true, okText: 'Eliminar' }))) return;
      try {
        await API.del('/products/' + id);
        U.toast('Producto eliminado.', 'success');
        load();
      } catch (e) {
        // Si tiene historial, ofrecer borrado definitivo (forzado)
        if (/movimientos/i.test(e.message)) {
          const ok = await U.confirm(
            'Este producto tiene historial (movimientos del kardex, compras o ventas). Si lo eliminas, también se borrará TODO ese historial y no se podrá deshacer. ¿Eliminar definitivamente?',
            { danger: true, okText: 'Eliminar todo' }
          );
          if (!ok) return;
          try {
            await API.del('/products/' + id + '?force=true');
            U.toast('Producto y su historial eliminados.', 'success');
            load();
          } catch (e2) { U.toast(e2.message, 'error'); }
        } else {
          U.toast(e.message, 'error');
        }
      }
    }

    function debounce(fn, ms) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; }

    await load();
  },
};

const router = require('express').Router();
const prisma = require('../prisma');
const ah = require('../utils/asyncHandler');
const ApiError = require('../utils/ApiError');

// Listar productos del kiosko activo (con filtros opcionales)
router.get('/', ah(async (req, res) => {
  const { q, categoryId, active } = req.query;
  const where = { kioskId: req.kioskId };
  if (q) where.OR = [
    { name: { contains: q, mode: 'insensitive' } },
    { code: { contains: q, mode: 'insensitive' } },
  ];
  if (categoryId) where.categoryId = Number(categoryId);
  if (active === 'true') where.active = true;
  if (active === 'false') where.active = false;

  const products = await prisma.product.findMany({
    where,
    include: { category: true, subcategory: true },
    orderBy: { name: 'asc' },
  });
  res.json(products);
}));

router.get('/:id', ah(async (req, res) => {
  const product = await prisma.product.findFirst({
    where: { id: Number(req.params.id), kioskId: req.kioskId },
    include: { category: true, subcategory: true },
  });
  if (!product) throw new ApiError(404, 'Producto no encontrado.');
  res.json(product);
}));

// Crear producto. Si trae stock inicial, se registra como movimiento INITIAL.
router.post('/', ah(async (req, res) => {
  const b = req.body;
  if (!b.code || !b.name) throw new ApiError(400, 'El código y el nombre son obligatorios.');

  const exists = await prisma.product.findFirst({ where: { kioskId: req.kioskId, code: b.code.trim() } });
  if (exists) throw new ApiError(400, `Ya existe un producto con el código ${b.code} en este kiosko.`);

  const stock = Number(b.stock) || 0;

  const product = await prisma.$transaction(async (tx) => {
    const p = await tx.product.create({
      data: {
        kioskId: req.kioskId,
        code: b.code.trim(),
        name: b.name.trim(),
        categoryId: b.categoryId ? Number(b.categoryId) : null,
        subcategoryId: b.subcategoryId ? Number(b.subcategoryId) : null,
        unit: b.unit || 'Unidad',
        supplier: b.supplier || null,
        cost: Number(b.cost) || 0,
        price: Number(b.price) || 0,
        minStock: Number(b.minStock) || 0,
        stock,
        active: b.active !== undefined ? !!b.active : true,
      },
    });
    if (stock > 0) {
      await tx.stockMovement.create({
        data: { kioskId: req.kioskId, productId: p.id, type: 'INITIAL', quantityIn: stock, reference: 'Stock inicial' },
      });
    }
    return p;
  });

  res.status(201).json(product);
}));

// Actualizar producto (no toca el stock directamente para no romper el kardex)
router.put('/:id', ah(async (req, res) => {
  const id = Number(req.params.id);
  const b = req.body;
  const product = await prisma.product.findFirst({ where: { id, kioskId: req.kioskId } });
  if (!product) throw new ApiError(404, 'Producto no encontrado.');

  if (b.code && b.code.trim() !== product.code) {
    const dup = await prisma.product.findFirst({ where: { kioskId: req.kioskId, code: b.code.trim() } });
    if (dup) throw new ApiError(400, `Ya existe un producto con el código ${b.code} en este kiosko.`);
  }

  const updated = await prisma.product.update({
    where: { id },
    data: {
      code: b.code !== undefined ? b.code.trim() : undefined,
      name: b.name !== undefined ? b.name.trim() : undefined,
      categoryId: b.categoryId !== undefined ? (b.categoryId ? Number(b.categoryId) : null) : undefined,
      subcategoryId: b.subcategoryId !== undefined ? (b.subcategoryId ? Number(b.subcategoryId) : null) : undefined,
      unit: b.unit,
      supplier: b.supplier,
      cost: b.cost !== undefined ? Number(b.cost) : undefined,
      price: b.price !== undefined ? Number(b.price) : undefined,
      minStock: b.minStock !== undefined ? Number(b.minStock) : undefined,
      active: b.active !== undefined ? !!b.active : undefined,
    },
  });
  res.json(updated);
}));

// Ajuste manual de stock (entrada o salida). Queda registrado en el kardex.
router.post('/:id/stock-adjustment', ah(async (req, res) => {
  const id = Number(req.params.id);
  const qty = Number(req.body.quantity);
  if (!qty) throw new ApiError(400, 'Ingrese una cantidad distinta de cero.');

  const product = await prisma.product.findFirst({ where: { id, kioskId: req.kioskId } });
  if (!product) throw new ApiError(404, 'Producto no encontrado.');

  const updated = await prisma.$transaction(async (tx) => {
    if (product.stock + qty < 0)
      throw new ApiError(400, `El ajuste dejaría el stock negativo (actual ${product.stock}).`);
    await tx.product.update({ where: { id }, data: { stock: { increment: qty } } });
    await tx.stockMovement.create({
      data: {
        kioskId: req.kioskId,
        productId: id,
        type: 'ADJUSTMENT',
        quantityIn: qty > 0 ? qty : 0,
        quantityOut: qty < 0 ? -qty : 0,
        reference: req.body.reason ? req.body.reason : 'Ajuste manual de stock',
      },
    });
    return tx.product.findUnique({ where: { id } });
  });
  res.json(updated);
}));

// Eliminar producto.
// Por defecto borra solo si NO tiene movimientos.
// Con ?force=true elimina también todo su historial (movimientos, compras, ventas, conteos).
router.delete('/:id', ah(async (req, res) => {
  const id = Number(req.params.id);
  const force = req.query.force === 'true';
  const product = await prisma.product.findFirst({ where: { id, kioskId: req.kioskId } });
  if (!product) throw new ApiError(404, 'Producto no encontrado.');

  const movements = await prisma.stockMovement.count({ where: { productId: id } });
  if (movements > 0 && !force) {
    // 409: el frontend ofrecerá el borrado forzado
    throw new ApiError(409, 'El producto tiene movimientos asociados.');
  }

  await prisma.$transaction(async (tx) => {
    // Eliminar dependencias para no violar las llaves foráneas
    await tx.stockMovement.deleteMany({ where: { productId: id } });
    await tx.saleItem.deleteMany({ where: { productId: id } });
    await tx.purchase.deleteMany({ where: { productId: id } });
    await tx.physicalInventoryItem.deleteMany({ where: { productId: id } });
    await tx.product.delete({ where: { id } });
  });
  res.json({ ok: true });
}));

module.exports = router;

