/* ===================================================
   Sistema del Kiosco — Sistema de diseño
   =================================================== */
:root {
  /* Neutrales */
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --border: #e7e9ee;
  --border-strong: #d6dae1;

  /* Texto */
  --text: #1a1d24;
  --text-2: #5b6472;
  --muted: #8a93a2;

  /* Marca */
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-soft: #eef0fe;
  --primary-ring: rgba(79, 70, 229, 0.16);

  /* Sidebar */
  --sb-bg: #14161d;
  --sb-bg-2: #1c1f29;
  --sb-text: #9aa3b2;
  --sb-text-hover: #ffffff;
  --sb-active: #4f46e5;

  /* Estados */
  --green: #0f9d58;
  --green-soft: #e6f6ee;
  --red: #e11d48;
  --red-soft: #fdeef1;
  --amber: #d97706;
  --amber-soft: #fdf3e3;
  --blue: #2563eb;
  --blue-soft: #e8f0ff;

  /* Radios y sombras */
  --r-sm: 8px;
  --r-md: 12px;
  --r-lg: 16px;
  --shadow-xs: 0 1px 2px rgba(16, 24, 40, 0.05);
  --shadow-sm: 0 1px 3px rgba(16, 24, 40, 0.08), 0 1px 2px rgba(16, 24, 40, 0.04);
  --shadow-md: 0 4px 12px rgba(16, 24, 40, 0.08), 0 2px 4px rgba(16, 24, 40, 0.04);
  --shadow-lg: 0 20px 48px rgba(16, 24, 40, 0.18);

  --sidebar-w: 256px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }

body {
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
  letter-spacing: -0.006em;
}

::selection { background: var(--primary-ring); }

/* Scrollbars discretos */
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-thumb { background: #c9cdd6; border-radius: 999px; border: 2px solid transparent; background-clip: content-box; }
*::-webkit-scrollbar-thumb:hover { background: #aeb4c0; background-clip: content-box; }

.app { display: flex; min-height: 100vh; }

/* ---------- Sidebar ---------- */
.sidebar {
  width: var(--sidebar-w);
  background: var(--sb-bg);
  color: var(--sb-text);
  display: flex;
  flex-direction: column;

