  display: flex; align-items: center; gap: 10px;
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.toast::before { content: 'ℹ'; }
.toast.success { border-left: 3px solid var(--green); }
.toast.success::before { content: '✓'; color: #34d399; }
.toast.error { border-left: 3px solid var(--red); }
.toast.error::before { content: '✕'; color: #fb7185; }
@keyframes slidein { from { transform: translateX(40px); opacity: 0; } to { transform: none; opacity: 1; } }

/* ---------- Utilidades ---------- */
.row-flex { display: flex; gap: 10px; align-items: center; }
.mt { margin-top: 16px; }
.right { text-align: right; }
.line-items th, .line-items td { padding: 9px 12px; }
.section-title { font-weight: 700; margin: 20px 0 10px; color: var(--text-2); font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em; }
.loader { text-align: center; padding: 60px; color: var(--muted); }
.loader::after { content: ''; display: inline-block; width: 22px; height: 22px; margin-left: 10px; border: 2.5px solid var(--border); border-top-color: var(--primary); border-radius: 50%; vertical-align: middle; animation: spin 0.7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .sidebar { transform: translateX(-100%); box-shadow: var(--shadow-lg); }
  .sidebar.open { transform: none; }
  .main { margin-left: 0; }
  .hamburger { display: block; }
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .view { padding: 18px; }
  .topbar { padding: 0 16px; }
  .today { display: none; }
}

