1	/* Módulo: Categorías y subcategorías */
2	window.Routes = window.Routes || {};
3	window.Routes.categorias = {
4	  title: 'Categorías',
5	  async render(view) {
6	    async function load() {
7	      view.innerHTML = '<div class="loader">Cargando categorías…</div>';
8	      const cats = await API.get('/categories');
9	      paint(cats);
10	    }
11	
12	    function paint(cats) {
13	      view.innerHTML = `
14	        <div class="panel">
15	          <div class="panel-head"><h2>Categorías de productos</h2>
16	            <button class="btn primary" id="btnCat">+ Nueva categoría</button></div>
17	          <div class="panel-body">
18	            ${cats.length === 0 ? '<div class="empty">Aún no hay categorías.</div>' : ''}
19	            <div class="cards">
20	            ${cats.map((c) => `
21	              <div class="kpi">
22	                <div class="row-flex" style="justify-content:space-between">
23	                  <strong style="font-size:16px">${U.escapeHtml(c.name)}</strong>
24	                  <button class="btn-icon" data-delcat="${c.id}" title="Eliminar">🗑️</button>
25	                </div>
26	                <div class="sub" style="margin:6px 0">${c._count.products} producto(s)</div>
27	                <div>
28	                  ${c.subcategories.map((s) => `<span class="badge gray" style="margin:2px 4px 2px 0">${U.escapeHtml(s.name)} <a href="#" data-delsub="${s.id}" style="color:inherit;text-decoration:none">✕</a></span>`).join('') || '<span class="text-muted">Sin subcategorías</span>'}
29	                </div>
30	                <button class="btn sm ghost mt" data-addsub="${c.id}">+ Subcategoría</button>
31	              </div>`).join('')}
32	            </div>
33	          </div>
34	        </div>`;
35	
36	      document.getElementById('btnCat').onclick = addCategory;
37	      view.querySelectorAll('[data-delcat]').forEach((b) => (b.onclick = () => delCategory(b.dataset.delcat)));
38	      view.querySelectorAll('[data-addsub]').forEach((b) => (b.onclick = () => addSub(b.dataset.addsub)));
39	      view.querySelectorAll('[data-delsub]').forEach((b) => (b.onclick = (e) => { e.preventDefault(); delSub(b.dataset.delsub); }));
40	    }
41	
42	    function addCategory() {
43	      const box = U.modal({
44	        title: 'Nueva categoría',
45	        bodyHtml: `<div class="field"><label>Nombre</label><input id="c_name" placeholder="Ej: Bebidas" /></div>`,
46	        footerHtml: `<button class="btn" data-c>Cancelar</button><button class="btn primary" data-s>Crear</button>`,
47	      });
48	      box.querySelector('[data-c]').onclick = U.closeModal;
49	      box.querySelector('[data-s]').onclick = async () => {
50	        try { await API.post('/categories', { name: box.querySelector('#c_name').value }); U.closeModal(); U.toast('Categoría creada.', 'success'); load(); }
51	        catch (e) { U.toast(e.message, 'error'); }
52	      };
53	    }
54	
55	    function addSub(catId) {
56	      const box = U.modal({
57	        title: 'Nueva subcategoría',
58	        bodyHtml: `<div class="field"><label>Nombre</label><input id="s_name" placeholder="Ej: Gaseosas" /></div>`,
59	        footerHtml: `<button class="btn" data-c>Cancelar</button><button class="btn primary" data-s>Crear</button>`,
60	      });
61	      box.querySelector('[data-c]').onclick = U.closeModal;
62	      box.querySelector('[data-s]').onclick = async () => {
63	        try { await API.post(`/categories/${catId}/subcategories`, { name: box.querySelector('#s_name').value }); U.closeModal(); U.toast('Subcategoría creada.', 'success'); load(); }
64	        catch (e) { U.toast(e.message, 'error'); }
65	      };
66	    }
67	
68	    async function delCategory(id) {
69	      if (!(await U.confirm('¿Eliminar esta categoría?', { danger: true, okText: 'Eliminar' }))) return;
70	      try { await API.del('/categories/' + id); U.toast('Categoría eliminada.', 'success'); load(); }
71	      catch (e) { U.toast(e.message, 'error'); }
72	    }
