31	            )}
32	          </div>
33	        </div>`;
34	      document.getElementById('btnNew').onclick = openForm;
35	    }
36	
37	    function openForm() {
38	      if (!products.length) { U.toast('Primero crea productos con stock.', 'error'); return; }
39	      const cart = [];
40	
41	      const opts = products.map((p) => `<option value="${p.id}" data-price="${p.price}" data-stock="${p.stock}">${U.escapeHtml(p.code)} · ${U.escapeHtml(p.name)} (stock ${p.stock})</option>`).join('');
42	      const box = U.modal({
43	        title: 'Nueva venta',
44	        wide: true,
45	        bodyHtml: `
46	          <div class="grid-2">
47	            <div class="field"><label>Fecha</label><input id="v_date" type="date" value="${U.today()}" /></div>
48	            <div class="field"><label>Tipo de venta</label><select id="v_type"><option value="CASH">Contado</option><option value="CREDIT">Crédito</option></select></div>
49	          </div>
50	          <div id="creditFields" hidden>
51	            <div class="grid-2">
52	              <div class="field"><label>Cliente</label><input id="v_customer" placeholder="Nombre del cliente" /></div>
53	              <div class="field"><label>Fecha límite de pago</label><input id="v_due" type="date" /></div>
54	            </div>
55	          </div>
56	          <p class="section-title">Productos</p>
57	          <div class="grid-3" style="align-items:end">
58	            <div class="field" style="margin:0"><label>Producto</label><select id="v_prod">${opts}</select></div>
59	            <div class="field" style="margin:0"><label>Cantidad</label><input id="v_qty" type="number" min="1" value="1" /></div>
60	            <button class="btn primary" id="v_add" style="height:38px">+ Agregar</button>
61	          </div>
62	          <div id="cart" class="mt"></div>
63	          <div class="right mt"><strong style="font-size:18px">Total: <span id="v_total">$0</span></strong></div>`,
64	        footerHtml: `<button class="btn" data-c>Cancelar</button><button class="btn success" data-s>Registrar venta (descuenta stock)</button>`,
65	      });
66	
67	      const typeSel = box.querySelector('#v_type');
68	      typeSel.onchange = () => { box.querySelector('#creditFields').hidden = typeSel.value !== 'CREDIT'; };
69	
70	      const renderCart = () => {
71	        const cartEl = box.querySelector('#cart');
72	        if (!cart.length) { cartEl.innerHTML = '<div class="empty">Agrega productos a la venta.</div>'; box.querySelector('#v_total').textContent = '$0'; return; }
73	        let total = 0;
74	        cartEl.innerHTML = `<div class="table-wrap"><table class="line-items"><thead><tr><th>Producto</th><th class="num">Cant.</th><th class="num">P. Unit</th><th class="num">Total</th><th></th></tr></thead><tbody>${cart.map((it, i) => {
75	          const lineTotal = it.qty * it.price; total += lineTotal;
76	          return `<tr><td>${U.escapeHtml(it.name)}</td><td class="num">${it.qty}</td><td class="num">${U.money(it.price)}</td><td class="num">${U.money(lineTotal)}</td><td><button class="btn-icon" data-rm="${i}">✕</button></td></tr>`;
77	        }).join('')}</tbody></table></div>`;
78	        box.querySelector('#v_total').textContent = U.money(total);
79	        cartEl.querySelectorAll('[data-rm]').forEach((b) => (b.onclick = () => { cart.splice(Number(b.dataset.rm), 1); renderCart(); }));
80	      };
81	
82	      box.querySelector('#v_add').onclick = () => {
83	        const sel = box.querySelector('#v_prod');
84	        const opt = sel.selectedOptions[0];
85	        const id = Number(sel.value);
86	        const qty = Number(box.querySelector('#v_qty').value);
87	        const stock = Number(opt.dataset.stock);
88	        if (qty <= 0) return U.toast('Cantidad inválida.', 'error');
89	        const already = cart.filter((c) => c.productId === id).reduce((a, c) => a + c.qty, 0);
90	        if (already + qty > stock) return U.toast(`Stock insuficiente (disponible ${stock}).`, 'error');
91	        const existing = cart.find((c) => c.productId === id);
92	        if (existing) existing.qty += qty;
93	        else cart.push({ productId: id, name: opt.textContent.split(' (stock')[0], qty, price: Number(opt.dataset.price) });
94	        renderCart();
95	      };
96	      renderCart();
97	
98	      box.querySelector('[data-c]').onclick = U.closeModal;
99	      box.querySelector('[data-s]').onclick = async () => {
100	        if (!cart.length) return U.toast('Agrega al menos un producto.', 'error');
101	        const type = typeSel.value;
102	        const payload = {
103	          type, date: box.querySelector('#v_date').value,
104	          items: cart.map((c) => ({ productId: c.productId, quantity: c.qty, unitPrice: c.price })),
105	        };
106	        if (type === 'CREDIT') {
107	          payload.customer = box.querySelector('#v_customer').value;
108	          payload.dueDate = box.querySelector('#v_due').value || null;
109	          if (!payload.customer.trim()) return U.toast('Ingresa el cliente para el crédito.', 'error');
110	        }
111	        try { await API.post('/sales', payload); U.closeModal(); U.toast('Venta registrada. Stock actualizado.', 'success'); load(); }
112	        catch (e) { U.toast(e.message, 'error'); }
113	      };
114	    }
115	
116	    await load();
117	  },
118	};
