        { danger: true, okText: 'Eliminar todo' }
      );
      if (!ok) return;
      try {
        await API.del('/kiosks/' + k.id);
        if (String(API.getKiosk()) === String(k.id)) API.setKiosk('');
        await window.refreshKiosks();
        U.toast('Kiosko eliminado.', 'success');
        load();
      } catch (e) { U.toast(e.message, 'error'); }
    }

    await load();
  },
};

