app.post('/save-doc-img', (req, res) => {
  const { name, data } = req.body;
  if (!name || !data) return res.status(400).json({ error: 'Faltan name o data' });
  const base64 = data.replace(/^data:image\/\w+;base64,/, '');
  const imgDir = path.join(__dirname, '..', 'public', 'docs', 'img');
  fs.mkdirSync(imgDir, { recursive: true });
  fs.writeFileSync(path.join(imgDir, name), Buffer.from(base64, 'base64'));
  res.json({ ok: true, saved: name });
});

