const path = require('path');
const fs = require('fs');
const express = require('express');
const cors = require('cors');

const app = express();

app.use(cors());
app.use(express.json({ limit: '10mb' }));

// Endpoint temporal para guardar capturas del manual (solo localhost)
app.post('/save-doc-img', (req, res) => {
  const { name, data } = req.body;
  if (!name || !data) return res.status(400).json({ error: 'Faltan name o data' });
  const base64 = data.replace(/^data:image\/\w+;base64,/, '');
  const imgDir = path.join(__dirname, '..', 'public', 'docs', 'img');
  fs.mkdirSync(imgDir, { recursive: true });
  fs.writeFileSync(path.join(imgDir, name), Buffer.from(base64, 'base64'));
  res.json({ ok: true, saved: name });
});

// API REST
app.use('/api', require('./routes'));

// Frontend (dashboard) servido como archivos estáticos
app.use(express.static(path.join(__dirname, '..', 'public')));

// Manejo central de errores
app.use((err, req, res, next) => {
  const status = err.status || 500;
  if (status === 500) console.error(err);
  // Errores conocidos de Prisma
  if (err.code === 'P2002') {
    return res.status(400).json({ error: 'Ya existe un registro con ese valor único.' });
  }
  res.status(status).json({ error: err.message || 'Error interno del servidor.' });
});

module.exports = app;

/* Módulo: Gestión de Usuarios (solo ADMIN) */
window.Routes = window.Routes || {};
window.Routes.usuarios = {
  title: 'Usuarios',
  async render(view) {
    const me = API.getUser();
    if (!me || me.role !== 'ADMIN') {
      view.innerHTML = `<div class="panel"><div class="panel-body">
        <h2 class="text-red">Acceso denegado</h2>
        <p class="text-muted">Solo los administradores pueden gestionar usuarios.</p>
      </div></div>`;
      return;
    }

    async function load() {
      view.innerHTML = '<div class="loader">Cargando usuarios…</div>';
      const users = await API.get('/users');
      paint(users);
    }

    function roleLabel(role) {
      return role === 'ADMIN'
        ? '<span class="badge blue">Admin</span>'
        : '<span class="badge gray">Operador</span>';
    }

    function paint(users) {
      view.innerHTML = `
        <div class="panel">
          <div class="panel-head">
            <h2>Gestión de Usuarios</h2>
            <button class="btn primary" id="btnNew">+ Nuevo usuario</button>
          </div>
          <div class="panel-body">
            ${U.table(
              [
                { key: 'username',  label: 'Usuario' },
                { key: 'name',      label: 'Nombre' },
                { key: 'role',      label: 'Rol',    render: (r) => roleLabel(r.role) },
                { key: 'active',    label: 'Estado', render: (r) => r.active ? '<span class="badge green">Activo</span>' : '<span class="badge gray">Inactivo</span>' },
                { key: 'createdAt', label: 'Creado', render: (r) => new Date(r.createdAt).toLocaleDateString('es-CO') },
                { key: 'acc', label: '', render: (r) => {
                  const self = r.id === me.id;
                  return `<button class="btn-icon" data-edit="${r.id}" title="Editar">${U.icon('pencil')}</button>${self ? '' : `<button class="btn-icon" data-del="${r.id}" title="Eliminar">${U.icon('trash-2')}</button>`}`;
                }},
              ],
              users,
              { empty: 'No hay usuarios registrados.' }
            )}
          </div>
        </div>`;

      document.getElementById('btnNew').onclick = () => openForm();
      view.querySelectorAll('[data-edit]').forEach((b) => b.onclick = () => openForm(users.find((u) => u.id == b.dataset.edit)));
      view.querySelectorAll('[data-del]').forEach((b)  => b.onclick = () => remove(b.dataset.del));
    }

    function openForm(u = null) {
      const isEdit = !!u;
      const isSelf = u && u.id === me.id;
      const box = U.modal({
        title: isEdit ? `Editar usuario · ${u.username}` : 'Nuevo usuario',
        bodyHtml: `
          <div class="grid-2">
            <div class="field"><label>Usuario *</label>
              <input id="u_username" value="${U.escapeHtml(u?.username || '')}" ${isEdit ? 'disabled' : ''} placeholder="sin espacios" /></div>
            <div class="field"><label>Nombre completo *</label>
              <input id="u_name" value="${U.escapeHtml(u?.name || '')}" /></div>
          </div>
          <div class="grid-2">
            <div class="field"><label>Rol</label>
              <select id="u_role" ${isSelf ? 'disabled' : ''}>
                <option value="OPERADOR" ${u?.role === 'OPERADOR' || !u ? 'selected' : ''}>Operador</option>
                <option value="ADMIN"    ${u?.role === 'ADMIN' ? 'selected' : ''}>Administrador</option>
              </select>
              ${isSelf ? '<span class="hint">No puedes cambiar tu propio rol.</span>' : ''}</div>
            <div class="field"><label>Estado</label>
              <select id="u_active" ${isSelf ? 'disabled' : ''}>
                <option value="true"  ${!u || u.active  ? 'selected' : ''}>Activo</option>
                <option value="false" ${u && !u.active  ? 'selected' : ''}>Inactivo</option>
              </select></div>
          </div>
          <div class="field"><label>${isEdit ? 'Nueva contraseña' : 'Contraseña *'} <span class="hint">${isEdit ? '(dejar en blanco para no cambiar)' : 'mínimo 6 caracteres'}</span></label>
            <input id="u_pass" type="password" placeholder="••••••••" /></div>`,
        footerHtml: `<button class="btn" data-c>Cancelar</button><button class="btn primary" id="u_save">Guardar</button>`,
      });
      box.querySelector('[data-c]').onclick = U.closeModal;
      box.querySelector('#u_save').onclick = async () => {
        const data = {
          name:   box.querySelector('#u_name').value.trim(),
          role:   isSelf ? u.role : box.querySelector('#u_role').value,
          active: isSelf ? u.active : box.querySelector('#u_active').value === 'true',
        };
        const pass = box.querySelector('#u_pass').value;
        if (pass) data.password = pass;
        if (!isEdit) {
          data.username = box.querySelector('#u_username').value.trim();
          if (!pass) return U.toast('La contraseña es obligatoria para usuarios nuevos.', 'error');
        }
        if (!data.name) return U.toast('El nombre es obligatorio.', 'error');
        try {
          if (isEdit) await API.put('/users/' + u.id, data);
          else await API.post('/users', data);
          U.closeModal(); U.toast('Usuario guardado.', 'success'); load();
        } catch (e) { U.toast(e.message, 'error'); }
      };
    }

    async function remove(id) {
      if (!(await U.confirm('¿Eliminar este usuario? Esta acción no se puede deshacer.', { danger: true, okText: 'Eliminar' }))) return;
      try { await API.del('/users/' + id); U.toast('Usuario eliminado.', 'success'); load(); }
      catch (e) { U.toast(e.message, 'error'); }
    }

    await load();
  },
};

/* Módulo: Administración de Kioskos */
window.Routes = window.Routes || {};
window.Routes.kioskos = {
  title: 'Kioskos',
  async render(view) {
    async function load() {
      view.innerHTML = '<div class="loader">Cargando kioskos…</div>';
      const kiosks = await API.get('/kiosks');
      paint(kiosks);
    }

    function paint(kiosks) {
      const activeId = API.getKiosk();
      view.innerHTML = `
        <div class="panel">
          <div class="panel-head"><h2>Kioskos (espacios)</h2>
            <button class="btn primary" id="btnNew">+ Nuevo kiosko</button></div>
          <div class="panel-body">
            <p class="text-muted" style="margin-bottom:14px">Cada kiosko maneja su propia información (productos, ventas, inventario y cartera) de forma totalmente independiente.</p>
            ${U.table(
              [
                { key: 'name',  label: 'Kiosko',    render: (r) => `${U.escapeHtml(r.name)} ${String(r.id) === String(activeId) ? '<span class="badge blue">Activo</span>' : ''}` },
                { key: 'prods', label: 'Productos', num: true, render: (r) => r._count.products },
                { key: 'sales', label: 'Ventas',    num: true, render: (r) => r._count.sales },
                { key: 'acc', label: '', render: (r) => `
                  ${String(r.id) === String(activeId) ? '' : `<button class="btn sm" data-use="${r.id}">Usar</button>`}
                  <button class="btn-icon" data-edit="${r.id}" title="Renombrar">${U.icon('pencil')}</button>
                  <button class="btn-icon" data-del="${r.id}"  title="Eliminar">${U.icon('trash-2')}</button>` },
              ],
              kiosks,
              { empty: 'No hay kioskos. Crea el primero.' }
            )}
          </div>
        </div>`;

      document.getElementById('btnNew').onclick = openForm;
      view.querySelectorAll('[data-use]').forEach((b) => (b.onclick = async () => {
        API.setKiosk(b.dataset.use); await window.refreshKiosks(); U.toast('Kiosko activo cambiado.', 'success'); load();
      }));
      view.querySelectorAll('[data-edit]').forEach((b) => (b.onclick = () => openForm(kiosks.find((k) => k.id == b.dataset.edit))));
      view.querySelectorAll('[data-del]').forEach((b)  => (b.onclick = () => remove(kiosks.find((k) => k.id == b.dataset.del))));
    }

    function openForm(k = null) {
      const isEdit = !!k;
      const box = U.modal({
        title: isEdit ? 'Renombrar kiosko' : 'Nuevo kiosko',
        bodyHtml: `
          <div class="field"><label>Nombre del kiosko</label><input id="k_name" value="${U.escapeHtml(k?.name || '')}" placeholder="Ej: Kiosco Tribuna Norte" /></div>
          ${isEdit ? '' : `<label class="row-flex" style="font-weight:500"><input type="checkbox" id="k_seed" checked style="width:auto"> Crear con las categorías sugeridas</label>`}`,
        footerHtml: `<button class="btn" data-c>Cancelar</button><button class="btn primary" data-s>${isEdit ? 'Guardar' : 'Crear'}</button>`,
      });
      box.querySelector('[data-c]').onclick = U.closeModal;
      box.querySelector('[data-s]').onclick = async () => {
        const name = box.querySelector('#k_name').value;
        try {
          if (isEdit) { await API.put('/kiosks/' + k.id, { name }); }
          else {
            const created = await API.post('/kiosks', { name, seedCategories: box.querySelector('#k_seed').checked });
            if (!API.getKiosk()) API.setKiosk(String(created.id));
          }
          U.closeModal(); await window.refreshKiosks(); U.toast(isEdit ? 'Kiosko actualizado.' : 'Kiosko creado.', 'success'); load();
        } catch (e) { U.toast(e.message, 'error'); }
      };
    }

    async function remove(k) {
      const ok = await U.confirm(
        `¿Eliminar el kiosko "${k.name}"? Se borrará TODA su información (productos, ventas, inventario, cartera). Esta acción no se puede deshacer.`,
        { danger: true, okText: 'Eliminar todo' }
      );
      if (!ok) return;
      try {
        await API.del('/kiosks/' + k.id);
        if (String(API.getKiosk()) === String(k.id)) API.setKiosk('');
        await window.refreshKiosks(); U.toast('Kiosko eliminado.', 'success'); load();
      } catch (e) { U.toast(e.message, 'error'); }
    }

    await load();
  },
};

