const router = require('express').Router();
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const prisma = require('../prisma');
const ah = require('../utils/asyncHandler');
const ApiError = require('../utils/ApiError');
const requireAuth = require('../middleware/requireAuth');

const SECRET = process.env.JWT_SECRET || 'kiosco_caballeriza_jwt_2026_secret';

function makeToken(user) {
  return jwt.sign(
    { id: user.id, username: user.username, name: user.name, role: user.role },
    SECRET,
    { expiresIn: '24h' }
  );
}

// Iniciar sesión
router.post('/login', ah(async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) throw new ApiError(400, 'Usuario y contraseña son requeridos.');
  const user = await prisma.user.findUnique({ where: { username: username.trim() } });
  if (!user || !user.active) throw new ApiError(401, 'Usuario o contraseña incorrectos.');
  const valid = await bcrypt.compare(password, user.password);
  if (!valid) throw new ApiError(401, 'Usuario o contraseña incorrectos.');
  const token = makeToken(user);
  res.json({ token, user: { id: user.id, username: user.username, name: user.name, role: user.role } });
}));

// Obtener usuario actual
router.get('/me', requireAuth, (req, res) => {
  res.json(req.user);
});

// Cambiar contraseña propia
router.post('/change-password', requireAuth, ah(async (req, res) => {
  const { current, newPass } = req.body;
  if (!current || !newPass) throw new ApiError(400, 'La contraseña actual y la nueva son requeridas.');
  if (newPass.length < 6) throw new ApiError(400, 'La nueva contraseña debe tener al menos 6 caracteres.');
  const user = await prisma.user.findUnique({ where: { id: req.user.id } });
  const valid = await bcrypt.compare(current, user.password);
  if (!valid) throw new ApiError(401, 'La contraseña actual es incorrecta.');
  await prisma.user.update({ where: { id: user.id }, data: { password: await bcrypt.hash(newPass, 10) } });
  res.json({ ok: true });
}));

module.exports = router;

