process.chdir('C:/Users/PREDATOR/Desktop/Documentos alberto/sistemaCaballeriza');
const prisma = require('./src/prisma');
const svc = require('./src/services/salesRecord.service');

(async () => {
  let kioskId;
  try {
    const k = await prisma.kiosk.create({ data: { name: 'TEST_RV_' + Math.floor(process.hrtime()[1]) } });
    kioskId = k.id;
    const p1 = await prisma.product.create({ data: { kioskId, code: 'T1', name: 'Agua Test', price: 1000, cost: 500, stock: 20, minStock: 2 } });
    const p2 = await prisma.product.create({ data: { kioskId, code: 'T2', name: 'Soda Test', price: 2000, cost: 900, stock: 20, minStock: 2 } });

    // Registro 1: agua 5 contado + 3 crédito a Ana(111); soda 2 crédito a Ana(111)
    const rec = await svc.create(kioskId, { note: 'test', items: [
      { productId: p1.id, cashQty: 5, creditQty: 3, customerCc: '111', customerName: 'Ana' },
      { productId: p2.id, cashQty: 0, creditQty: 2, customerCc: '111', customerName: 'Ana' },
    ]});
    console.log('Registro creado. cashTotal=%d creditTotal=%d (esp 5000 / 7000)', rec.cashTotal, rec.creditTotal);

    await svc.approve(kioskId, rec.id);

    const a1 = await prisma.product.findUnique({ where: { id: p1.id } });
    const a2 = await prisma.product.findUnique({ where: { id: p2.id } });
    console.log('Stock agua=%d (esp 12), soda=%d (esp 18)', a1.stock, a2.stock);

    const sales = await prisma.sale.findMany({ where: { kioskId }, include: { items: true, customer: true } });
    const cash = sales.filter(s => s.type === 'CASH');
    const credit = sales.filter(s => s.type === 'CREDIT');
    console.log('Ventas CASH=%d (esp 1), CREDIT=%d (esp 1 - un crédito por cliente)', cash.length, credit.length);
    console.log('Crédito: nº=%s cliente=%s cc=%s total=%d items=%d (esp nº1, Ana, 111, 7000, 2 items)',
      credit[0].creditNumber, credit[0].customer.name, credit[0].customer.cc, credit[0].total, credit[0].items.length);

    // Registro 2: otro crédito a la MISMA Ana(111) -> número secuencial 2, mismo cliente
    const rec2 = await svc.create(kioskId, { items: [{ productId: p1.id, cashQty: 0, creditQty: 1, customerCc: '111', customerName: 'Ana' }] });
    await svc.approve(kioskId, rec2.id);
    const credits2 = await prisma.sale.findMany({ where: { kioskId, type: 'CREDIT' }, orderBy: { creditNumber: 'asc' } });
    const customers = await prisma.customer.findMany({ where: { kioskId } });
    console.log('Créditos totales=%d nºs=%s | clientes=%d (esp 2 créditos [1,2], 1 cliente reutilizado)',
      credits2.length, credits2.map(c => c.creditNumber).join(','), customers.length);

    // Stock insuficiente
    try {
      const recX = await svc.create(kioskId, { items: [{ productId: p2.id, cashQty: 999, creditQty: 0 }] });
      await svc.approve(kioskId, recX.id);
      console.log('ERROR: debió fallar por stock');
    } catch (e) { console.log('OK bloquea stock insuficiente:', e.message); }

    console.log('\n✅ Prueba de integración OK');
  } catch (e) {
    console.error('❌ FALLO:', e);
  } finally {
    if (kioskId) await prisma.kiosk.delete({ where: { id: kioskId } }).catch(() => {});
    await prisma.$disconnect();
  }
})();

