// Prueba de integración del registro de ventas multi-cliente (kiosko temporal, se borra).
const ROOT = 'C:/Users/PREDATOR/Desktop/Documentos alberto/sistemaCaballeriza';
const prisma = require(ROOT + '/src/prisma');
const svc = require(ROOT + '/src/services/salesRecord.service');

(async () => {
  let kioskId;
  try {
    const k = await prisma.kiosk.create({ data: { name: 'TEST_RV_' + process.hrtime()[1] } });
    kioskId = k.id;
    const agua = await prisma.product.create({ data: { kioskId, code: 'T1', name: 'Agua', price: 1000, cost: 500, stock: 20, minStock: 2 } });
    const soda = await prisma.product.create({ data: { kioskId, code: 'T2', name: 'Soda', price: 2000, cost: 900, stock: 20, minStock: 2 } });

    // Agua: 5 contado + crédito 3 a Ana(111) y 2 a Beto(222). Soda: 2 crédito a Ana(111).
    const rec = await svc.create(kioskId, { items: [
      { productId: agua.id, cashQty: 5, credits: [
        { qty: 3, customerCc: '111', customerName: 'Ana' },
        { qty: 2, customerCc: '222', customerName: 'Beto' },
      ] },
      { productId: soda.id, cashQty: 0, credits: [{ qty: 2, customerCc: '111', customerName: 'Ana' }] },
    ]});
    console.log('cashTotal=%d (esp 5000) creditTotal=%d (esp 9000)', rec.cashTotal, rec.creditTotal);

    await svc.approve(kioskId, rec.id);

    const a = await prisma.product.findUnique({ where: { id: agua.id } });
    const s = await prisma.product.findUnique({ where: { id: soda.id } });
    console.log('Stock agua=%d (esp 10), soda=%d (esp 18)', a.stock, s.stock);

    const sales = await prisma.sale.findMany({ where: { kioskId }, include: { items: true, customer: true }, orderBy: { id: 'asc' } });
    const cash = sales.filter((x) => x.type === 'CASH');
    const credit = sales.filter((x) => x.type === 'CREDIT');
    console.log('CASH=%d (esp 1), CREDIT=%d (esp 2: Ana y Beto)', cash.length, credit.length);
    credit.forEach((c) => console.log('  crédito #%d %s (CC %s) total=%d items=%d', c.creditNumber, c.customer.name, c.customer.cc, c.total, c.items.length));
    const customers = await prisma.customer.findMany({ where: { kioskId } });
    console.log('Clientes=%d (esp 2)', customers.length);

    console.log('\n✅ Multi-cliente OK');
  } catch (e) {
    console.error('❌ FALLO:', e);
  } finally {
    if (kioskId) await prisma.kiosk.delete({ where: { id: kioskId } }).catch(() => {});
    await prisma.$disconnect();
  }
})();

